    7.4.0

     Il passaggio di caratteri non validi ora genera un avviso di deprecazione.
     Il risultato verrà comunque calcolato come se i caratteri non validi non esistessero.

  &reftitle.examples;



    Esempio di bindec


<?php
echo bindec('110011') . "\n";
echo bindec('000110011') . "\n";

echo bindec('111');
?>


    &example.outputs;


51
51
7







    bindec interpreta l'input come interi senza segno


<?php
/*
 * La lezione di questo esempio sta nell'output
 * piuttosto che nel codice PHP stesso.
 */

$magnitude_lower = pow(2, (PHP_INT_SIZE * 8) - 2);
p($magnitude_lower - 1);
p($magnitude_lower, 'Si nota il rollover?  Osservarlo al prossimo giro...');

p(PHP_INT_MAX, 'PHP_INT_MAX');
p(~PHP_INT_MAX, 'interpretato come uno in più di PHP_INT_MAX');

if (PHP_INT_SIZE == 4) {
    $note = 'interpretato come il più grande intero senza segno';
} else {
    $note = 'interpretato come il più grande intero senza segno
              (18446744073709551615) ma alterato dalla precisione dei float';
}
p(-1, $note);


function p($input, $note = '') {
    echo "input:        $input\n";

    $format = '%0' . (PHP_INT_SIZE * 8) . 'b';
    $bin = sprintf($format, $input);
    echo "binario:      $bin\n";

    ini_set('precision', 20);  // Per leggibilità sui sistemi a 64 bit.
    $dec = bindec($bin);
    echo 'bindec():     ' . $dec . "\n";

    if ($note) {
        echo "NOTA:         $note\n";
    }

    echo "\n";
}
?>


    &example.outputs.32bit;


